-- Generated by generate_legendary_gem_items.py: a legendary gem item's own rank, by item guid, and the rank a socketed one carries. Not dc_item_affix.gem_rank, which is a normal gem's tier.
CREATE TABLE IF NOT EXISTS `dc_legendary_gem_rank` (item_guid BIGINT UNSIGNED NOT NULL PRIMARY KEY, gem_rank INT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SET @dc_column_exists=(SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='dc_item_affix' AND column_name='legendary_rank');
SET @dc_ddl=IF(@dc_column_exists=0,'ALTER TABLE dc_item_affix ADD COLUMN legendary_rank INT UNSIGNED NULL','DO 0');
PREPARE dc_artisan_ddl FROM @dc_ddl;
EXECUTE dc_artisan_ddl;
DEALLOCATE PREPARE dc_artisan_ddl;
